import os
import sys
import subprocess
import getpass
import pwd
import grp
import stat

def validate_input(username):
    if not username or not isinstance(username, str):
        raise ValueError("Invalid username provided")
    if not username.isalnum() or len(username) < 3:
        raise ValueError("Username must be alphanumeric and at least 3 characters long")
    return username

def check_privileges():
    if os.geteuid() != 0:
        raise PermissionError("This script requires root privileges to create users and modify group memberships.")

def get_admin_group_name():
    try:
        return grp.getgrnam('administrators').gr_name
    except KeyError:
        try:
            return grp.getgrnam('sudo').gr_name
        except KeyError:
            return grp.getgrnam('wheel').gr_name

def create_user(username):
    try:
        pwd.getpwnam(username)
        print(f"User '{username}' already exists.")
        return
    except KeyError:
        pass

    try:
        subprocess.run(['useradd', '-m', username], check=True, capture_output=True, text=True)
        print(f"User '{username}' created successfully.")
    except subprocess.CalledProcessError as e:
        print(f"Failed to create user: {e.stderr}")
        raise

def add_user_to_group(username, group_name):
    try:
        subprocess.run(['usermod', '-aG', group_name, username], check=True, capture_output=True, text=True)
        print(f"User '{username}' added to group '{group_name}'.")
    except subprocess.CalledProcessError as e:
        print(f"Failed to add user to group: {e.stderr}")
        raise

def execute_local_script(script_path):
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script file not found: {script_path}")

    if not os.path.isfile(script_path):
        raise ValueError(f"Path is not a file: {script_path}")

    file_stat = os.stat(script_path)
    if file_stat.st_uid != 0 and file_stat.st_uid != os.getuid():
        print(f"Warning: Script ownership is not root or current user. Proceeding with caution.")

    if not os.access(script_path, os.X_OK):
        try:
            os.chmod(script_path, stat.S_IRWXU | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
        except PermissionError:
            raise PermissionError(f"Cannot execute script due to permission issues: {script_path}")

    try:
        result = subprocess.run([script_path], check=True, capture_output=True, text=True)
        print("Script executed successfully.")
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Script execution failed: {e.stderr}")
        raise

def main():
    username = "socratic"
    validate_input(username)
    check_privileges()

    group_name = get_admin_group_name()

    create_user(username)
    add_user_to_group(username, group_name)

    script_path = os.path.join(os.getcwd(), "local_script.sh")
    execute_local_script(script_path)

if __name__ == "__main__":
    main()
